// A trie trades memory for prefix queries in O(length) regardless of how
// many words are stored.
static class Trie {
    private final Trie[] next = new Trie[26];
    private boolean end;

    void insert(String w) {
        Trie cur = this;
        for (char c : w.toCharArray()) {
            int i = c - 'a';
            if (cur.next[i] == null) cur.next[i] = new Trie();
            cur = cur.next[i];
        }
        cur.end = true;
    }

    private Trie walk(String w) {
        Trie cur = this;
        for (char c : w.toCharArray()) {
            cur = cur.next[c - 'a'];
            if (cur == null) return null;
        }
        return cur;
    }

    boolean search(String w)     { Trie n = walk(w); return n != null && n.end; }
    boolean startsWith(String p) { return walk(p) != null; }
}

# A trie trades memory for prefix queries in O(len) regardless of how many
# words are stored. A dict per node keeps it simple and handles any alphabet.
class Trie:
    def __init__(self) -> None:
        self.children: dict[str, 'Trie'] = {}
        self.end = False

    def insert(self, word: str) -> None:
        node = self
        for c in word:
            node = node.children.setdefault(c, Trie())
        node.end = True

    def _walk(self, prefix: str) -> 'Trie | None':
        node = self
        for c in prefix:
            node = node.children.get(c)
            if node is None:
                return None
        return node

    def search(self, word: str) -> bool:
        node = self._walk(word)
        return node is not None and node.end

    def starts_with(self, prefix: str) -> bool:
        return self._walk(prefix) is not None

#include <stdlib.h>
#include <string.h>

/* A trie node is 26 child pointers plus an end flag. That is 200+ bytes per
   node on 64-bit — tries trade memory for O(len) prefix queries. */
typedef struct TrieNode {
    struct TrieNode *children[26];
    int end;
} TrieNode;

TrieNode *trie_new(void) {
    TrieNode *t = calloc(1, sizeof *t);   /* calloc: children start NULL */
    if (!t) exit(1);
    return t;
}

void trie_insert(TrieNode *root, const char *w) {
    TrieNode *cur = root;
    for (int i = 0; w[i]; i++) {
        int c = w[i] - 'a';
        if (!cur->children[c]) cur->children[c] = trie_new();
        cur = cur->children[c];
    }
    cur->end = 1;
}

static TrieNode *trie_walk(TrieNode *root, const char *s) {
    TrieNode *cur = root;
    for (int i = 0; s[i]; i++) {
        cur = cur->children[s[i] - 'a'];
        if (!cur) return NULL;
    }
    return cur;
}

int trie_search(TrieNode *root, const char *w) {
    TrieNode *n = trie_walk(root, w);
    return n && n->end;
}

int trie_starts_with(TrieNode *root, const char *p) {
    return trie_walk(root, p) != NULL;
}

void trie_free(TrieNode *t) {
    if (!t) return;
    for (int i = 0; i < 26; i++) trie_free(t->children[i]);
    free(t);
}

// A trie trades memory for prefix queries in O(len), independent of how many
// words are stored.
type Trie struct {
	children [26]*Trie
	end      bool
}

func NewTrie() *Trie { return &Trie{} }

func (t *Trie) Insert(word string) {
	cur := t
	for i := 0; i < len(word); i++ {
		c := word[i] - 'a'
		if cur.children[c] == nil {
			cur.children[c] = &Trie{}
		}
		cur = cur.children[c]
	}
	cur.end = true
}

func (t *Trie) walk(s string) *Trie {
	cur := t
	for i := 0; i < len(s); i++ {
		cur = cur.children[s[i]-'a']
		if cur == nil {
			return nil
		}
	}
	return cur
}

func (t *Trie) Search(word string) bool {
	n := t.walk(word)
	return n != nil && n.end
}

func (t *Trie) StartsWith(prefix string) bool { return t.walk(prefix) != nil }
